style.css:
@-moz-document domain("olx.com.br") {
/* ============================================================
     OLX Brasil runs a Next.js app on its own "olx-ui" component
     library (olx-core-*, olx-adcard, olx-header, olx-dropdown,
     olx-modal, …) — a DIFFERENT frontend from the European OLX
     sites. Colors are literal hex on stable, BEM-style class
     names (no design-token :root vars exposed, no hashed
     classes), so surfaces are flipped structurally from those
     stable component classes.
     ============================================================ */

  :root { color-scheme: dark !important; }

  /* ---- Base page ---- */
  html, body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  /* ---- Soften every default light border into a dark hairline ---- */
  * { border-color: #2d333b !important; }

  /* ============================================================
     Header / global nav (white bar -> deep neutral dark)
     ============================================================ */
  #header,
  header.olx-header,
  .olx-header,
  .olx-header__main-menu,
  nav.olx-header__main-menu {
    background-color: #0d1117 !important;
    border-color: #2d333b !important;
  }
  .olx-header a,
  .olx-header button,
  .olx-header__main-menu a { color: #e6edf3 !important; }
  /* Navbar dropdown panels */
  .olx-navbar__dropdown,
  [class*="navbar__dropdown"],
  [role="menu"], [role="listbox"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }

  /* ============================================================
     Auth flow (conta.olx.com.br) — the login/register pages run a
     separate shell with the "focus" header variant and a
     styled-components divider. Both ship literal white surfaces the
     main-site header rules don't reach.
     ============================================================ */
  header.olx-focus-header,
  .olx-focus-header {
    background-color: #0d1117 !important;
    border-color: #2d333b !important;
  }
  /* "Ou acesse com" divider: an absolutely-positioned label span carries
     a white bg to mask the rule line under it. Repaint it onto the card
     surface + lift the grey label to a readable tone. The Tailwind margin
     utility on the wrapper churns between redesigns (mt-6 -> mt-5), so
     cover both variants. */
  .flex.mb-2.mt-6 span,
  .flex.mb-2.mt-5 span {
    background-color: #1c2128 !important;
    color: #9aa6b0 !important;
  }
  /* Register (/cadastro) renders its form on a white styled-components
     card the main rules don't reach — meanwhile our generic input/label
     rules already darken the fields and lighten the labels, so the copy
     ends up light-on-white. Dark the CSS-module shell + its card panel
     (hashed child) so the whole form coheres. */
  [class*="mainWrapper_mainContainer"] {
    background-color: #14181d !important;
  }
  [class*="mainWrapper_mainContainer"] > div > div {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* Its form copy (olx-text variants, radio labels, password-rule hints
     and helper/error captions) all carry near-black hex — dark-on-dark
     now the card is dark. Lift within the auth shell only. */
  [class*="mainWrapper_mainContainer"] .olx-text,
  [class*="mainWrapper_mainContainer"] .olx-radio__content .olx-text {
    color: #c4cdd6 !important;
  }
  [class*="mainWrapper_mainContainer"] .olx-text--body-large,
  [class*="mainWrapper_mainContainer"] .olx-text--body-medium {
    color: #e6edf3 !important;
  }
  [class*="mainWrapper_mainContainer"] .olx-text--caption,
  [class*="mainWrapper_mainContainer"] [id*="text-input-error"] {
    color: #9aa6b0 !important;
  }
  /* Its "ou" divider label is an absolutely-positioned white chip that
     masks the rule line — repaint it onto the card surface. */
  [class*="mainWrapper_mainContainer"] span[class*="typo-body-small"] {
    background-color: #1c2128 !important;
  }
  /* Login (/acesso) card ships a "Preciso de ajuda" footer strip on a
     near-white #f5f6f7 styled-component bg — only 35px tall, so it slips
     under the audit's height floor and glares at the foot of the dark
     card. Its classes are hashed (sc-*), but it's reliably the card's
     last-child footer; the conta auth app is Next.js (#__next) vs the
     main SPA (#root), so scope there and flatten it onto the card. */
  #__next .olx-container--outlined > div:last-child > div {
    background-color: transparent !important;
  }

  /* ============================================================
     Layout containers / generic surfaces
     #2d333b borders already softened above; flatten white/grey
     wrappers to the base or an elevated surface as appropriate.
     ============================================================ */
  main, section, .olx-container {
    background-color: transparent !important;
  }
  /* Outlined containers (white boxes with a hairline) -> elevated card */
  .olx-container--outlined,
  div[data-ds-component="DS-Container"].olx-container--outlined {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* ============================================================
     Search bar (grey field) -> dark input
     ============================================================ */
  .olx-core-input-element,
  .olx-core-input-textarea-element,
  .olx-text-input__input-field,
  .olx-text-input__input-container,
  input[type="text"], input[type="search"], input[type="number"],
  textarea {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  ::placeholder { color: #7d8893 !important; opacity: 1 !important; }
  /* Native select dropdowns (filters, sort, location) */
  .olx-dropdown__native,
  select {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .olx-dropdown__native option,
  select option { background-color: #1c2128 !important; color: #e6edf3 !important; }
  /* Autocomplete / suggestion panels */
  [class*="autocomplete"] ul,
  [class*="autocomplete__list"],
  [class*="oraculo"] ul {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* olx-core-singleselect — the custom dropdown behind the search-results
     "Tipo de Anúncio" / "Ordenar por" controls (and the header location
     picker). Its trigger ships a literal-white bg but is only 36px tall, so
     it slips under the audit's height floor and glares as a white pill; its
     open menu paints each option with near-black text (#1A1D23) on a
     transparent bg (dark-on-dark) and highlights the selected row with a
     light #EFF1F5 surface. Dark the trigger + menu, lift the option text,
     and settle the selected/hover row onto an elevated dark tone (its
     orange check keeps marking the selection). */
  .olx-core-singleselect__trigger {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }
  .olx-core-singleselect__value,
  .olx-core-singleselect__trigger-content,
  .olx-core-singleselect__placeholder { color: #e6edf3 !important; }
  .olx-core-singleselect__option-list,
  .olx-core-singleselect__menu {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .olx-core-singleselect__option,
  .olx-core-singleselect__option-content { color: #e6edf3 !important; }
  .olx-core-singleselect__option--selected,
  .olx-core-singleselect__option--highlighted,
  .olx-core-singleselect__option:hover {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }

  /* ============================================================
     OLX accent (raw #F28000 orange) refined for dark
     ------------------------------------------------------------
     Keep the instantly-recognizable OLX orange identity, but pull
     the lightness up slightly and the saturation down a touch so
     it reads cleanly on the near-black palette without glaring.
     ============================================================ */
  .olx-core-button--primary,
  button.olx-core-button--primary,
  a.olx-core-button--primary {
    background-color: #f2901f !important;
    color: #1a1206 !important;
    border-color: #f2901f !important;
  }
  .olx-core-button--primary:hover,
  a.olx-core-button--primary:hover { background-color: #ffa436 !important; }

  /* Secondary button (peach bg / orange text) -> subtle dark-amber */
  .olx-core-button--secondary,
  button.olx-core-button--secondary {
    background-color: #3a2a14 !important;
    color: #f6b35e !important;
    border-color: #5a4220 !important;
  }
  /* Neutral / outline buttons (white) -> elevated dark */
  .olx-core-button--neutral,
  button.olx-core-button--neutral,
  .olx-core-button--link {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  a.olx-core-button--link { background-color: transparent !important; color: #f6b35e !important; }

  /* ============================================================
     Ad / listing cards (home + search, vertical + horizontal)
     ============================================================ */
  .olx-adcard,
  .olx-adcard__vertical,
  .olx-adcard__horizontal,
  section.olx-adcard {
    background-color: #1c2128 !important;
    border: 1px solid #2d333b !important;
    border-radius: 8px !important;
    color: #c4cdd6 !important;
  }
  /* Image placeholder block inside cards (grey #EFF1F5) */
  .olx-adcard__media,
  picture {
    background-color: #21262d !important;
  }
  /* Loading skeletons paint a light shimmer (linear-gradient of
     #eff1f5 -> #cfd4dd) that flashes bright on the dark page during
     every load — swap the gradient for a flat dark placeholder. */
  .olx-core-skeleton,
  [class*="skeleton"] {
    background-image: none !important;
    background-color: #21262d !important;
  }
  /* Card title / price text */
  .olx-adcard__title,
  .olx-adcard a.olx-core-link--main { color: #e6edf3 !important; }
  .olx-adcard__price { color: #ffffff !important; font-weight: 600 !important; }
  .olx-adcard__location,
  .olx-adcard__date,
  .olx-adcard a.olx-core-link--grey { color: #8b949e !important; }
  /* Favourite (heart) toggle — OLX floats it as a 32px circular FAB over the
     card photo on a literal-white bg. At 32px it slips under the audit's size
     floor, so every card glares a bright white dot top-right. Settle the
     circle onto an elevated dark surface; the heart icon (and its filled
     favourited state) stays legible. */
  .olx-adcard__favorite,
  [class*="adcard__favorite"],
  [data-testid="adcard-favorite"] {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
  }

  /* ============================================================
     Badges — keep semantic hue, settle onto dark
     info/secondary lavender (#F0E6FF) -> muted dark-violet chip
     ============================================================ */
  .olx-core-badge--info,
  .olx-core-badge--secondary {
    background-color: #2a2440 !important;
    color: #c9b6f5 !important;
    border-color: #3a3358 !important;
  }
  .olx-core-badge--success {
    background-color: #102a23 !important;
    color: #6fd6a8 !important;
    border-color: #1f6b54 !important;
  }
  .olx-core-badge--warning {
    background-color: #322a12 !important;
    color: #e6c463 !important;
    border-color: #6b5520 !important;
  }
  .olx-core-badge--danger,
  .olx-core-badge--error {
    background-color: #3a1b16 !important;
    color: #f0a193 !important;
    border-color: #c2402b !important;
  }

  /* ============================================================
     Search-results page: filters sidebar + form controls
     ============================================================ */
  [data-testid="filter-box-clodoview"],
  [data-testid*="filter"],
  [class*="filter-box"],
  label {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  [data-testid="filter-box-clodoview"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    border-radius: 8px !important;
  }
  /* Subcategory-header icon tile: a small (~36px) rounded #EFF1F5 chip
     holding the category glyph — under the audit's size floor, so it
     slips past as a bright square glaring in the dark filters rail.
     Settle onto the elevated media tone; the colored glyph stays legible. */
  [class*="SubcategoryFilterHeader_icon"] {
    background-color: #21262d !important;
    border-color: #2d333b !important;
  }

  /* Filter form controls (checkboxes / radios) — olx-ui paints the box
     itself on a `::before` pseudo (element bg is transparent), so the
     element-bg audit is blind to it: every UNCHECKED box renders a
     glaring literal-white square/circle down the filters rail. Settle
     the empty box onto an elevated dark surface with a light-grey
     hairline so it reads as an outline, and keep the CHECKED state on
     the brand OLX purple (#6E0AD6) with its white tick intact. */
  .olx-core-checkbox-radio__input::before {
    background-color: #1c2128 !important;
    border-color: #6b7681 !important;
  }
  .olx-core-checkbox-radio__input:checked::before {
    background-color: #6e0ad6 !important;
    border-color: #6e0ad6 !important;
  }
  /* Toggle switch (e.g. "Anunciantes bem avaliados") ships a light-grey
     #cfd4dd OFF track that glares on dark; darken only the unchecked
     track (scope with :not(:checked)) so the native ON accent + white
     knob are untouched. */
  .olx-core-toggle-switch:not(:checked) {
    background-color: #484f58 !important;
  }

  /* Advertising placeholders (white/grey ad slots) -> blend into base.
     Attribute substring matching is case-sensitive, so cover both the
     lower-case slot classes and the hashed React `AdvertisingAnchor`
     (sticky bottom ad) container, whose light-grey panel leaks. */
  [data-testid="advertising-placeholder"],
  [class*="advertising"],
  [class*="Advertising"],
  [class*="anchor-container"] {
    background-color: #14181d !important;
  }

  /* Breadcrumbs */
  [data-ds-component="DS-Breadcrumb"],
  [data-ds-component="DS-Breadcrumb"] *,
  .olx-breadcrumb a,
  nav[aria-label*="readcrumb"] a { color: #9aa6b0 !important; }
  [data-ds-component="DS-Breadcrumb"] a:hover { color: #e6edf3 !important; }

  /* ============================================================
     Individual ad / item page
     ------------------------------------------------------------
     The ad detail content lives under the stable #adview wrapper.
     Its cards (price box, seller, safety tips) are styled-component
     wrappers (ad__sc-* hashed names) carrying literal #FFF. Flatten
     all of those to transparent so the dark base shows through, then
     re-elevate the few stable, distinct cards.
     ============================================================ */
  #adview { background-color: #14181d !important; }
  #adview [class*="ad__sc-"] {
    background-color: transparent !important;
    border-color: #2d333b !important;
  }
  /* Price box + gallery surrounds (stable ids) -> elevated card */
  #price-box-container,
  [class*="price-box"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }
  #item-gallery-image,
  button#item-gallery-image,
  [class*="gallery"] {
    background-color: #0d1117 !important;
  }
  /* Title + price */
  h1, h2, h3 { color: #e6edf3 !important; }
  [class*="price"] strong,
  [class*="price-box"] h2 { color: #ffffff !important; }

  /* OLX "secondary" (purple) design tokens used as RAW vars via inline
     styles in the ad body — e.g. the price-box discount-coupon banner
     paints `background: var(--color-secondary-70)` (light lavender)
     with `--color-secondary-120/130` dark-purple copy on top. The
     class-based secondary overrides can't reach inline-var usage, so
     flip the scale at the token level within #adview: light surface
     token -> dark violet chip, deep text shades -> a readable violet. */
  #adview {
    --color-secondary-70: #2a2440 !important;
    --color-secondary-120: #c9b6f5 !important;
    --color-secondary-130: #c9b6f5 !important;
  }
  /* The "ver número" phone-reveal control OLX auto-generates inside the
     ad description is a hashed styled-component span carrying the raw
     saturated OLX purple (#6E0AD6) on BOTH color and -webkit-text-fill,
     so it reads dark-on-dark. Target its stable data-element hook (the
     hashed class churns) and lift to the readable violet. */
  #adview [data-element="button_show-phone"] {
    color: #b794f6 !important;
    -webkit-text-fill-color: #b794f6 !important;
  }

  /* ============================================================
     Text utilities — olx-ui ships Tailwind-style text-color and
     typography classes carrying literal near-black hex; on dark
     they read as black-on-dark. Lift them to the readable scale
     while keeping the dark/secondary hierarchy.
     ============================================================ */
  .text-neutral-130, .text-neutral-120, .text-neutral-130 *,
  [class*="typo-title"], [class*="typo-body-large"],
  [class*="typo-body-medium"] {
    color: #e6edf3 !important;
  }
  .text-neutral-110, .text-neutral-100, .text-neutral-90,
  [class*="typo-body-small"], [class*="typo-caption"],
  [class*="typo-overline"] {
    color: #9aa6b0 !important;
  }
  /* OLX secondary accent is a saturated purple (#6E0AD6) that fails
     contrast on dark — lift to a lighter, readable violet, same hue. */
  .text-secondary-100, .text-secondary-110, .text-secondary-90,
  .olx-link--secondary, .olx-core-link--secondary {
    color: #b794f6 !important;
  }

  /* olx-link (distinct from olx-core-link) — default dark text and the
     purple secondary variant; both unreadable on dark. */
  .olx-link, .olx-link--small, .olx-link--caption, .olx-link--main {
    color: #c4cdd6 !important;
  }
  .olx-link--secondary, a.olx-link[class*="secondary"] { color: #b794f6 !important; }

  /* ------------------------------------------------------------
     The "--main" link variant is the worst dark-on-dark offender:
     olx-ui paints it via `color: var(--link-color)` where
     `--link-color` resolves to the raw saturated OLX purple
     (#6E0AD6, luminance ~0.04). A bare `.olx-link--main`/
     `.olx-core-link--main { color: ... !important }` TIES that
     class on specificity and loses on cascade order, so the purple
     survives. Re-scope the override from the stable app/section IDs
     (#root wraps the SPA, #header the global nav/skip-links,
     #adview the ad body) to raise specificity and WIN — lifting the
     purple action links (Simular empréstimo, Exibir telefone, the
     skip-links, breadcrumb home, "Ver descrição completa", etc.) to
     a readable lifted violet of the same hue. */
  #root .olx-link--main,
  #root .olx-core-link--main,
  #header .olx-link--main,
  #header .olx-core-link--main,
  #adview .olx-link--main,
  #adview .olx-core-link--main {
    color: #b794f6 !important;
    -webkit-text-fill-color: #b794f6 !important;
  }
  #root .olx-link--main:hover,
  #root .olx-core-link--main:hover,
  #header .olx-link--main:hover,
  #header .olx-core-link--main:hover,
  #adview .olx-link--main:hover,
  #adview .olx-core-link--main:hover {
    color: #d2bdff !important;
    -webkit-text-fill-color: #d2bdff !important;
  }

  /* Tabs (home "Categorias / Tudo" nav + olx-tabs labels) — dark and
     purple-selected labels lifted to the readable scale / accent. */
  [class*="tabs-navigation__tab"],
  .olx-tabs__tab-label,
  .olx-tabs__tab { color: #9aa6b0 !important; }
  [class*="tabs-navigation__tab"][aria-selected="true"],
  [class*="tabs-navigation__tab--active"],
  .olx-tabs__tab--active .olx-tabs__tab-label,
  .olx-tabs__tab[aria-selected="true"] .olx-tabs__tab-label {
    color: #f6b35e !important;
  }
  /* Keep semantic feedback colors readable on dark */
  [class*="text-feedback-success"] { color: #6fd6a8 !important; }
  [class*="text-feedback-error"], [class*="text-feedback-danger"] { color: #f0a193 !important; }
  [class*="text-feedback-warning"] { color: #e6c463 !important; }

  /* ============================================================
     Third-party consent / CMP dialog. OLX uses Google Funding
     Choices (.fc-consent-root), whose stylesheet is injected AFTER
     our theme — so a bare `.fc-dialog` rule TIES on specificity and
     LOSES on source order, leaving a blinding white sheet on first
     visit. Scope every rule from `.fc-consent-root` to out-specify
     the CMP and dark the whole sheet + lift its dark Material text.
     ============================================================ */
  .fc-consent-root .fc-dialog,
  .fc-consent-root .fc-dialog-content,
  .fc-consent-root .fc-choice-dialog,
  .fc-consent-root .fc-header,
  .fc-consent-root .fc-footer,
  [class*="adopt-"][class*="dialog"] {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .fc-consent-root .fc-dialog h1,
  .fc-consent-root .fc-dialog h2,
  .fc-consent-root .fc-dialog p,
  .fc-consent-root .fc-dialog li,
  .fc-consent-root .fc-dialog span,
  .fc-consent-root .fc-dialog div,
  .fc-consent-root .fc-dialog-headline,
  .fc-consent-root .fc-dialog-content {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  /* Logo tile + FAQ panel keep a literal white bg */
  .fc-consent-root .fc-faq-icon,
  .fc-consent-root .fc-faq-contents {
    background-color: #14181d !important;
  }
  .fc-consent-root .fc-dialog hr,
  .fc-consent-root .fc-dialog [class*="divider"] {
    background-color: #2d333b !important;
    border-color: #2d333b !important;
  }
  /* "Manage options" preferences panel: the sticky header bar, each
     per-purpose card (.fc-preference-container) and the manage-vendors
     row all ship a literal white surface with a light hairline — our
     lifted near-white text ghosts onto them. Settle them onto an
     elevated dark surface so the copy + toggles read. */
  .fc-consent-root .fc-dialog-header,
  .fc-consent-root .fc-preference-container,
  .fc-consent-root .fc-navigation-button,
  .fc-consent-root .fc-manage-vendors,
  .fc-consent-root [class*="preferences-container"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .fc-consent-root .fc-preference-container {
    background-color: #21262d !important;
  }

  /* ============================================================
     Alert / notification boxes (olx-alertbox) — the default
     variant ships a near-white #EFF1F5 surface with near-black
     text, which leaks a bright panel on the dark item page. Settle
     it onto an elevated dark surface with readable copy; keep the
     semantic variants (success/warning/error) tinted but dark.
     ============================================================ */
  .olx-alertbox,
  .olx-alertbox--default,
  [class*="alertbox"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }
  .olx-alertbox .olx-text,
  .olx-alertbox--default .olx-text,
  [class*="alertbox"] .olx-text,
  .olx-alertbox p,
  .olx-alertbox span { color: #e6edf3 !important; }
  .olx-alertbox--success {
    background-color: #102a23 !important;
    border-color: #1f6b54 !important;
  }
  .olx-alertbox--warning {
    background-color: #322a12 !important;
    border-color: #6b5520 !important;
  }
  .olx-alertbox--error,
  .olx-alertbox--danger {
    background-color: #3a1b16 !important;
    border-color: #c2402b !important;
  }

  /* In-flow / pre-rendered dialog body copy (olx-text) carries a
     near-black color that becomes dark-on-dark once a modal opens. */
  .olx-modal__content .olx-text,
  [class*="modal__content"] .olx-text,
  .olx-modal__dialog .olx-text { color: #c4cdd6 !important; }

  /* ============================================================
     Modals (favourite, share, report, consent, delivery)
     ============================================================ */
  .olx-modal__dialog,
  .olx-modal__content,
  [data-ds-component="DS-Modal"],
  [class*="modal__dialog"],
  [class*="modal__content"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }
  .olx-modal__overlay,
  [class*="modal__overlay"],
  [class*="backdrop"] {
    background-color: rgba(0, 0, 0, 0.6) !important;
  }

  /* ============================================================
     Dividers
     ============================================================ */
  hr, .olx-divider, [data-ds-component="DS-Divider"] {
    border-color: #2d333b !important;
    background-color: #2d333b !important;
  }

  /* ============================================================
     Generic links
     ============================================================ */
  a { color: #c4cdd6; }
  a:hover { color: #ffffff !important; }
  .olx-core-link--main { color: #e6edf3 !important; }
  .olx-core-link--grey { color: #9aa6b0 !important; }

  /* ============================================================
     Footer
     ============================================================ */
  footer,
  .olx-footer,
  [data-ds-component="DS-Footer"],
  [class*="footer"] {
    background-color: #0d1117 !important;
    color: #9aa6b0 !important;
    border-top: 1px solid #2d333b !important;
  }
  footer a,
  .olx-footer a,
  [data-ds-component="DS-Footer-Link"] { color: #9aa6b0 !important; }
  footer a:hover { color: #e6edf3 !important; }

  /* ============================================================
     Taboola sponsored-content widget (trc_* / videoCube) at the foot of
     the search results renders bright-white video tiles with black
     titles. Dark the tiles, drop the white hover-fade overlay, and
     lift the labels so the unit blends into the dark page.
     ============================================================ */
  [id^="internal_trc"], [id*="taboola"],
  .trc_rbox, .trc_rbox_outer, .videoCube, .trc_spotlight_item,
  .trc_popover, .trc_popover_fade {
    background-color: #1c2128 !important;
  }
  .trc_exclude_overlay { background-color: transparent !important; }
  .videoCube .video-title, .videoCube .video-label,
  .trc_spotlight_item .video-title, .trc-main-label,
  .trc_spotlight_item .trc-main-label *,
  .trc_popover, .trc_popover * { color: #c4cdd6 !important; }

  /* ============================================================
     Scrollbar polish
     ============================================================ */
  ::-webkit-scrollbar { width: 12px; height: 12px; }
  ::-webkit-scrollbar-track { background: #0d1117; }
  ::-webkit-scrollbar-thumb { background: #2d333b; border-radius: 6px; }
  ::-webkit-scrollbar-thumb:hover { background: #3a424c; }
}
